<script setup lang="ts">
import { computed } from 'vue';
import { CheckCircle2, XCircle } from '@lucide/vue';
import AppLayout from '../../Layouts/AppLayout.vue';
defineOptions({ layout: AppLayout });
const props=defineProps<{test:any}>(); type SnapshotItem={id:number;standard_value:number|string;reading_value:number|string;correction:number|string;is_within_limit:boolean|null;group_order:number|null;group_name:string|null;reference_media:string|null;unit:string|null;point_order:number|null}; const snapshotGroups=computed(()=>{const groups=new Map<number,{order:number;name:string|null;media:string|null;items:SnapshotItem[]}>();for(const item of props.test.items as SnapshotItem[]){if(item.group_order==null)continue;if(!groups.has(item.group_order))groups.set(item.group_order,{order:item.group_order,name:item.group_name,media:item.reference_media,items:[]});groups.get(item.group_order)!.items.push(item)}return [...groups.values()].sort((a,b)=>a.order-b.order).map(group=>({...group,items:[...group.items].sort((a,b)=>(a.point_order??Infinity)-(b.point_order??Infinity))}))}); const groupAverage=(items:SnapshotItem[])=>{if(!items.length)return null;const sum=items.reduce((total,item)=>total+BigInt(Math.round(Number(item.correction)*10000)),0n);const count=BigInt(items.length);const absolute=sum<0n?-sum:sum;const rounded=absolute/count+((absolute%count)*2n>=count?1n:0n);return Number(sum<0n?-rounded:rounded)/10000}; const legacyItems=computed(()=> (props.test.items as SnapshotItem[]).filter(item=>item.group_order==null)); const snapshotUnit=computed(()=>{const units=[...new Set((props.test.items as SnapshotItem[]).map(item=>item.unit))];return units.length===1?units[0]:null}); const hasToleranceSnapshot=computed(()=>props.test.min_correction_snapshot!=null&&props.test.max_correction_snapshot!=null); const statusClass=(status:string)=>({OK:'bg-emerald-500',NG:'bg-red-500',SPARE:'bg-blue-500',SERVICE:'bg-amber-500',NA:'bg-slate-500'}[status]??'bg-slate-500');
</script>
<template><div class="mx-auto max-w-5xl space-y-4"><div class="rounded-2xl p-5 text-center text-white shadow-lg" :class="statusClass(test.status)"><div class="text-xs opacity-80">Status</div><div class="text-3xl font-extrabold">{{ test.status }}</div></div><div class="info-card"><h3 class="card-title">Info Alat</h3><div class="info-row"><span>Kode Alat</span><strong>{{ test.instrument.code }}</strong></div><div class="info-row"><span>Jenis</span><span>{{ test.instrument.type?.name }}</span></div><div class="info-row"><span>Lokasi</span><span>{{ test.instrument.factory?.name }} / {{ test.instrument.department?.name }}</span></div><div class="info-row"><span>Merk / Kapasitas</span><span>{{ test.instrument.brand?.name }} / {{ test.instrument.capacity?.name }}</span></div><div class="info-row"><span>Spesifikasi</span><span>{{ test.instrument.specification?.name ?? '—' }}</span></div><div class="info-row"><span>Toleransi</span><span v-if="hasToleranceSnapshot">{{ test.min_correction_snapshot }} s/d {{ test.max_correction_snapshot }} {{ snapshotUnit ?? '' }}</span><span v-else>Tidak tersedia</span></div></div><div class="info-card"><h3 class="card-title">Info Uji</h3><div class="info-row"><span>Tanggal Uji</span><span>{{ test.test_date }}</span></div><div class="info-row"><span>Next Test</span><span>{{ test.next_test_date }}</span></div><div class="info-row"><span>Tester</span><span>{{ test.tester?.name }}</span></div><div class="info-row"><span>Rata-rata Koreksi</span><span>{{ test.avg_correction ?? '—' }} {{ snapshotUnit ?? '' }}</span></div><div class="info-row"><span>Status otomatis tersimpan</span><span v-if="test.computed_status" class="badge" :class="test.computed_status==='OK'?'ok':'ng'">{{ test.computed_status }}</span><span v-else>Tidak dihitung</span></div><div class="info-row"><span>Status efektif</span><strong>{{ test.status }}</strong></div><div class="info-row"><span>Catatan</span><span>{{ test.notes ?? '—' }}</span></div></div><div v-if="test.dimension_checks.length>0" class="info-card"><h3 class="card-title">Hasil Pemeriksaan Ukuran</h3><div v-for="check in test.dimension_checks" :key="check.id" class="info-row"><span>{{ check.label }} ({{ check.min_value }} s/d {{ check.max_value }} {{ check.unit }})</span><span>{{ check.measured_value }} {{ check.unit }} <span class="badge" :class="check.is_within_range?'ok':'ng'">{{ check.is_within_range?'OK':'NG' }}</span></span></div><p class="note">Hasil ukuran tidak mengubah status pengujian.</p></div><div v-if="test.items.length>0" class="info-card"><h3 class="card-title">Hasil Uji</h3><details v-for="(group,index) in snapshotGroups" :key="group.order" :open="index===0" class="group-card"><summary>{{ group.name ?? 'Nama grup tidak tersedia' }} · {{ group.items.length }} titik</summary><div class="space-y-3 p-3"><p class="note">Media referensi: {{ group.media ?? 'Tidak tersedia' }} · Rata-rata: {{ groupAverage(group.items) ?? '—' }} {{ group.items[0]?.unit ?? '' }}</p><div v-for="item in group.items" :key="item.id" class="item-row"><div><div class="font-semibold">Standar {{ item.standard_value }} {{ item.unit ?? '' }}</div><div class="text-xs text-slate-500">Penunjukan {{ item.reading_value }} · Koreksi {{ item.correction }}</div></div><span v-if="item.is_within_limit!=null" class="badge" :class="item.is_within_limit?'ok':'ng'">{{ item.is_within_limit?'OK':'NG' }}</span></div></div></details><p v-if="legacyItems.length" class="note">Data lama tidak memiliki snapshot grup lengkap.</p></div></div></template>
<style scoped>.info-card{border:1px solid #e2e8f0;border-radius:1rem;background:#fff;padding:1rem;box-shadow:0 4px 16px rgba(15,23,42,.04)}.card-title{margin:0 0 .75rem;font-size:.875rem;font-weight:800}.info-row{display:flex;justify-content:space-between;gap:1rem;border-bottom:1px solid #f8fafc;padding:.5rem 0;font-size:.8125rem;color:#172033}.info-row>span:first-child{color:#64748b}.badge{display:inline-flex;border-radius:999px;padding:.2rem .5rem;font-size:.65rem;font-weight:800}.badge.ok{background:#dcfce7;color:#15803d}.badge.ng{background:#fee2e2;color:#b91c1c}.group-card{margin-top:.75rem;overflow:hidden;border:1px solid #e2e8f0;border-radius:.75rem}.group-card summary{cursor:pointer;background:#fff7ed;padding:.8rem;font-size:.8125rem;font-weight:700;color:#9a3412}.item-row{display:flex;align-items:center;justify-content:space-between;gap:.75rem;border-radius:.625rem;background:#f8fafc;padding:.75rem}.note{font-size:.75rem;color:#64748b}</style>
